// ---- PROFILE ----
const DEFAULT_PROFILE = {
  tokens: 0, arcadeSeconds: ARCDE_START_SEC, qSinceToken: 0,
  bestStreak: 0, dailyStreak: 0, bestDailyStreak: 0, activityDays: [], fullPracticeDraft: null, totalCorrect: 0, totalAttempts: 0,
  highScores: { pacman: 0, snake: 0, pong: 0, watersort: 0, tetris: 0, doom: 0, pressurewash: 0, "2048": 0, breakout: 0, flappy: 0, minesweeper: 0, connect4: 0, wordgame: 0, sudoku: 0, solitaire: 0, hopper: 0, stack: 0, doodle: 0, wordscape: 0, blackjack: 0, tictactoe: 0, blockblast: 0, bubbles: 0, invaders: 0, racing: 0, drift: 0, dirtbike: 0, battleships: 0 },
  soundOn: true, history: [], seen: {}, served: {}, lastServed: {}, recentQuestions: [], recentFamilies: [], selectionSequence: 0, qlog: {}, bookmarks: [], curve: "pt4", college: null, scholarships: null, garage: null, lastPlayed: {}, favorites: [], skillStats: {}, vocabStats: null, updatedAt: 0
};
let profile = JSON.parse(JSON.stringify(DEFAULT_PROFILE));

function loadProfile() {
  try { const p = JSON.parse(localStorage.getItem(PROFILE_KEY)); if (p && typeof p === "object") { Object.keys(DEFAULT_PROFILE).forEach((k) => { if (p[k] !== undefined) profile[k] = p[k]; }); Object.keys(p).forEach((k) => { if (DEFAULT_PROFILE[k] === undefined && k !== "dirty" && k !== "syncedAt") profile[k] = p[k]; }); } } catch (e) {}
  if (!Array.isArray(profile.history)) profile.history = [];
  ["seen", "served", "lastServed", "qlog"].forEach((key) => {
    if (!profile[key] || typeof profile[key] !== "object" || Array.isArray(profile[key])) profile[key] = {};
  });
  if (!Array.isArray(profile.recentQuestions)) profile.recentQuestions = [];
  if (!Array.isArray(profile.recentFamilies)) profile.recentFamilies = [];
  if (!Array.isArray(profile.activityDays)) profile.activityDays = [];
  profile.activityDays = [...new Set(profile.activityDays.filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d)))].sort().slice(-730);
  refreshDailyStreak();
  profile.recentQuestions = profile.recentQuestions.filter((id) => byId(id)).slice(-50);
  if (!Number.isSafeInteger(profile.selectionSequence) || profile.selectionSequence < 0) profile.selectionSequence = 0;
}
function saveProfile() { try { cloud.queue(); } catch (e) {} try { localStorage.setItem(PROFILE_KEY, JSON.stringify(profile)); } catch (e) {} try { cloud.queue(); } catch (e) {} }

// ---- HISTORY ----
function loadHistory() {
  try { const h = JSON.parse(localStorage.getItem(HISTORY_KEY)); if (Array.isArray(h)) profile.history = h; } catch (e) {}
  if (!Array.isArray(profile.history)) profile.history = [];
}
function saveHistory() { try { localStorage.setItem(HISTORY_KEY, JSON.stringify(profile.history)); } catch (e) {} }

function makeAttemptRecord() {
  const totalQ = state.keys.reduce((s, k) => s + state.counts[k], 0);
  const totalA = totalAnswered();
  const totalC = totalCorrect();
  const practiceKind = state.keys.some((k) => state.plan[k].moduleOnly === "drill") ? "topic" : "test";
  const secScores = {};
  state.keys.forEach((sec) => {
    const qids = sectionQids(sec);
    const a = answeredCount(qids), c = correctCount(qids);
    if (practiceKind === "topic") {
      secScores[sec] = { answered: a, correct: c };
    } else if (ACT_SCALE[sec]) {
      const raw = Math.round((c / Math.max(a, 1)) * ACT_MAX_RAW[sec]);
      secScores[sec] = { actScale: actScale(sec, raw), answered: a, correct: c };
    } else {
      const est = estimateSection(sec, state.routes[sec]);
      secScores[sec] = { score: est.point, answered: a, correct: c };
    }
  });
  return {
    id: state.attemptId, testType: state.cfg.testType, section: state.cfg.section, total: state.cfg.total,
    actSection: state.cfg.actSection, satModule: state.cfg.satModule, keys: state.keys.slice(),
    startedAt: state.startedAt || Date.now(), finishedAt: Date.now(), elapsed: state.elapsed,
    totalAnswered: totalA, totalCorrect: totalC,
    accuracy: totalA ? Math.round((totalC / totalA) * 100) : 0,
    bestStreak: profileBestStreak(), tokensEarned: sessionTokensEarned,
    unlocks: sessionUnlocks.slice(), routes: { ...state.routes },
    answers: { ...state.answers }, savedPlan: JSON.parse(JSON.stringify(state.plan)),
    practiceKind, scoreEligible: practiceKind === "test",
    secScores, domainStats: domainStatsAny(state.keys, state.plan, state.answers),
    // per-question log so the score predictor can weigh question difficulty
    qlog: Object.keys(state.answers).filter((id) => byId(id)).map((id) => [id, state.answers[id] === byId(id).ans ? 1 : 0])
  };
}

function domainStatsAny(keys, plan, answers) {
  const out = {};
  keys.forEach((sec) => {
    const qids = (plan[sec] && plan[sec].mods) ? plan[sec].mods.reduce((a, m) => a.concat(m || []), []) : [];
    qids.forEach((id) => {
      const a = answers[id]; if (a == null) return;
      const q = byId(id);
      if (!out[q.domain]) out[q.domain] = { correct: 0, total: 0 };
      out[q.domain].total++;
      if (a === q.ans) out[q.domain].correct++;
    });
  });
  return out;
}

function finalizeAttempt(force) {
  if (!state.attemptId) return;
  const rec = makeAttemptRecord();
  rec.done = !!state.done;
  const idx = profile.history.findIndex((h) => h.id === rec.id);
  if (idx >= 0) profile.history[idx] = rec; else profile.history.unshift(rec);
  if (profile.history.length > 120) profile.history = profile.history.slice(0, 120);
  saveHistory(); saveProfile();
  try { cloud.push(); } catch (e) {}
}

function profileBestStreak() {
  return profile.bestDailyStreak || 0;
}

function localDayKey(date = new Date()) {
  const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');
  return y+'-'+m+'-'+d;
}
function dayOrdinal(key) { const [y,m,d]=key.split('-').map(Number); return Math.round(Date.UTC(y,m-1,d)/86400000); }
function refreshDailyStreak(now = new Date()) {
  const days=[...new Set(profile.activityDays||[])].sort();let best=0,run=0,prev=null;
  for(const day of days){const n=dayOrdinal(day);run=prev!==null&&n===prev+1?run+1:1;best=Math.max(best,run);prev=n;}
  const today=dayOrdinal(localDayKey(now)),last=days.length?dayOrdinal(days[days.length-1]):-Infinity;
  profile.dailyStreak=(last===today||last===today-1)?run:0;profile.bestDailyStreak=Math.max(profile.bestDailyStreak||0,best);profile.bestStreak=profile.bestDailyStreak;return profile.dailyStreak;
}
function recordDailyActivity(now = new Date()) {
  const key=localDayKey(now),days=profile.activityDays=profile.activityDays||[];
  if(!days.includes(key))days.push(key);profile.activityDays=[...new Set(days)].sort().slice(-730);refreshDailyStreak(now);
}

// ---- STATE HELPERS ----
function curSection() { return state.keys[state.secIdx]; }
function currentMods() { return state.plan[curSection()].mods; }
function currentQids() { return currentMods()[state.modIdx] || []; }
function sectionQids(key) { return (state.plan[key].mods || []).reduce((a, m) => a.concat(m || []), []); }
function answeredCount(qids) { return qids.filter((id) => state.answers[id] != null).length; }
function correctCount(qids) { return qids.filter((id) => state.answers[id] === byId(id).ans).length; }
function totalAnswered() { return Object.keys(state.answers).length; }
function totalCorrect() { return correctCount(Object.keys(state.answers)); }

function fmtTime(sec) { const m = Math.floor(sec / 60); return m + ":" + String(sec % 60).padStart(2, "0"); }
function escapeHtml(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }

// Score curves. Only the College Board table is official; the other two are the same table shifted,
// to show how a harder or easier test date's curve changes your score.
const CURVES = {
  pt4: { label: "Official — SAT Practice Test 4 (College Board, 2023)", short: "SAT Practice Test 4 curve (2023)", sat: 0, act: 0 },
  strict: { label: "Strict — official 2023 curve minus 20 points (like an easier test form)", short: "strict curve (2023 table −20)", sat: -20, act: -1 },
  generous: { label: "Generous — official 2023 curve plus 20 points (like a harder test form)", short: "generous curve (2023 table +20)", sat: 20, act: 1 }
};
function curCurve() { return CURVES[profile.curve] || CURVES.pt4; }
const clampSat = (v) => Math.max(200, Math.min(800, v));
function estimateSection(section, route) {
  const qids = sectionQids(section);
  const answered = answeredCount(qids);
  const correct = correctCount(qids);
  if (!answered) return { lo: 200, hi: 200, point: null, answered: 0, correct: 0 };
  const maxRaw = section === "rw" ? 66 : 54;
  const raw = Math.round((correct / answered) * maxRaw);
  const row = CURVE[section][Math.min(raw, CURVE[section].length - 1)];
  const sh = curCurve().sat, lo = clampSat(row[0] + sh), hi = clampSat(row[1] + sh);
  const point = route === "harder" ? hi : route === "easier" ? lo : Math.round((lo + hi) / 2);
  return { lo, hi, point, answered, correct };
}

function actScale(section, raw) {
  const rows = ACT_SCALE[section];
  for (let i = 0; i < rows.length; i++) { if (raw >= rows[i][0] && raw <= rows[i][1]) return rows[i][2]; }
  return 1;
}
function estimateActSection(key) {
  const qids = sectionQids(key);
  const answered = answeredCount(qids);
  const correct = correctCount(qids);
  if (!answered) return { scale: null, answered: 0, correct: 0 };
  const raw = Math.round((correct / answered) * ACT_MAX_RAW[key]);
  return { scale: Math.max(1, Math.min(36, actScale(key, raw) + curCurve().act)), answered, correct, raw };
}

function domainStats(section, qids) {
  const stats = {};
  DOMAINS[section].forEach((d) => { stats[d] = { correct: 0, total: 0 }; });
  qids.forEach((id) => {
    const a = state.answers[id]; if (a == null) return;
    const q = byId(id);
    stats[q.domain].total++;
    if (a === q.ans) stats[q.domain].correct++;
  });
  return stats;
}
function workOnList(section, qids) {
  const stats = domainStats(section, qids);
  return DOMAINS[section].filter((d) => stats[d].total > 0 && stats[d].correct / stats[d].total < 0.75)
    .sort((a, b) => (stats[a].correct / stats[a].total) - (stats[b].correct / stats[b].total));
}

