// ---- AUDIO ----
let audioCtx = null;
function ensureAudio() { if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)(); }
function playTone(freq, dur, type, vol) {
  if (!profile.soundOn) return;
  try {
    ensureAudio();
    const o = audioCtx.createOscillator(), g = audioCtx.createGain();
    o.type = type || "sine"; o.frequency.value = freq;
    g.gain.value = Math.min(vol || 0.12, 0.3);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.connect(g); g.connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime + dur);
  } catch (e) {}
}
function sndCorrect() { playTone(523, .08, "sine", .1); setTimeout(() => playTone(659, .08, "sine", .1), 70); setTimeout(() => playTone(784, .12, "sine", .1), 140); }
function sndWrong() { playTone(200, .2, "sawtooth", .08); }
function sndCoin() { playTone(880, .06, "sine", .1); setTimeout(() => playTone(1100, .08, "sine", .08), 50); }
function sndChomp() { playTone(220, .05, "square", .06); setTimeout(() => playTone(260, .05, "square", .06), 60); }
function sndUnlock() { [523,659,784,1047].forEach((f,i) => setTimeout(() => playTone(f,.12,"sine",.1), i*90)); }
function sndGameOver() { [400,350,300,250].forEach((f,i) => setTimeout(() => playTone(f,.2,"triangle",.08), i*140)); }
function sndTick() { playTone(1000, .03, "sine", .05); }

// ---- CONFETTI ----
const confCanvas = document.getElementById("confettiCanvas");
const confCtx = confCanvas.getContext("2d");
let confetti = [];
function resizeConfetti() { confCanvas.width = innerWidth; confCanvas.height = innerHeight; }
addEventListener("resize", resizeConfetti); resizeConfetti();
function burstConfetti(n) {
  const colors = ["#f59e0b","#ef4444","#06d6a0","#3b82f6","#a855f7","#f97316"];
  for (let i = 0; i < n; i++) {
    confetti.push({ x: innerWidth/2 + (Math.random()-.5)*60, y: innerHeight/2, vx: (Math.random()-.5)*10, vy: -6-Math.random()*7, size: 4+Math.random()*5, color: colors[Math.floor(Math.random()*colors.length)], life: 1 });
  }
}
function animConfetti() {
  confCtx.clearRect(0, 0, confCanvas.width, confCanvas.height);
  confetti = confetti.filter((p) => p.life > 0);
  confetti.forEach((p) => { p.x += p.vx; p.vy += .12; p.y += p.vy; p.life -= .018; confCtx.globalAlpha = Math.max(0, p.life); confCtx.fillStyle = p.color; confCtx.fillRect(p.x, p.y, p.size, p.size); });
  confCtx.globalAlpha = 1;
  requestAnimationFrame(animConfetti);
}
animConfetti();

