function renderVocabSummary() {
  const el = document.getElementById("vocabStart"); if (!el) return;
  const stats = profile.vocabStats;
  if (!stats || !stats.total || !(stats.total.r + stats.total.w)) { el.style.display = "none"; return; }
  const total = stats.total.r + stats.total.w;
  const acc = Math.round((stats.total.r / total) * 100);
  const words = Object.keys(stats.words || {}).length;
  el.style.display = "block";
  el.innerHTML = '<div class="st-mini-h">📚 Vocab practice</div><p class="small muted" style="margin:0 0 10px">' + words + ' word' + (words === 1 ? '' : 's') + ' practiced · ' + acc + '% correct · best streak ' + (stats.bestStreak || 0) + '. Arcade practice — never counted in your estimated score.</p><button type="button" class="secondary" id="btnVocabGame">Play Vocab Sprint</button>';
  const btn = document.getElementById("btnVocabGame");
  if (btn) btn.addEventListener("click", () => { openArcade(); arcade.select("wordgame"); });
}
function renderStart() {
  document.querySelectorAll("#typePicker .pick").forEach((b) => b.classList.toggle("selected", b.dataset.type === state.cfg.testType));
  const isAct = state.cfg.testType === "act";
  $("satSectionWrap").style.display = isAct ? "none" : "block";
  $("actNote").style.display = isAct ? "block" : "none";
  $("actSectionWrap").style.display = isAct ? "block" : "none";
  const showModule = !isAct && state.cfg.section !== "both";
  $("satModuleWrap").style.display = showModule ? "block" : "none";
  if (!isAct) {
    document.querySelectorAll("#sectionPicker .pick").forEach((b) => b.classList.toggle("selected", b.dataset.section === state.cfg.section));
    document.querySelectorAll("#satModulePicker .pick").forEach((b) => b.classList.toggle("selected", b.dataset.module === (state.cfg.satModule || "full")));
  } else {
    document.querySelectorAll("#actSectionPicker .pick").forEach((b) => b.classList.toggle("selected", b.dataset.actSection === (state.cfg.actSection || "all")));
  }
  const maxQ = maxTotalFor(state.cfg);
  if (state.cfg.total > maxQ) state.cfg.total = maxQ;
  $("lengthMaxNote").textContent = "(up to " + maxQ + " available for this selection)";
  $("customLen").max = String(maxQ);
  document.querySelectorAll("#lengthPicker .pick").forEach((b) => b.classList.toggle("selected", Number(b.dataset.n) === state.cfg.total));
  const isPreset = Array.from(document.querySelectorAll("#lengthPicker .pick")).some((b) => Number(b.dataset.n) === state.cfg.total);
  $("customLen").value = isPreset ? "" : state.cfg.total;
  const hasSaved = !state.done && (state.view === "test" || state.view === "routing" || Object.keys(state.answers).length > 0);
  $("resumeBox").style.display = hasSaved ? "block" : "none";
  if (hasSaved) $("resumeInfo").textContent = "You have a session in progress with " + Object.keys(state.answers).length + " answered. Pick up where you left off.";
  renderHistorySummary();
  const cs = $("curveSelect");
  if (!cs.options.length) Object.keys(CURVES).forEach((k) => { const o = document.createElement("option"); o.value = k; o.textContent = CURVES[k].label; cs.appendChild(o); });
  cs.value = profile.curve in CURVES ? profile.curve : "pt4";
  $("curveNote").textContent = isAct ? "ACT sections use the chart from ACT's free practice test; the published sample stops around scale 6, so very low raw scores are app estimates. Strict/Generous move each section 1 point. The Composite follows ACT's current rule: English + Math + Reading." : "Uses the " + curCurve().short + ". The SAT doesn't publish a curve for each test date, so this is an official released practice table, and every score here is an estimate, not an official score.";
  const bm = (profile.bookmarks || []).filter((id) => byId(id));
  $("bookmarkStart").style.display = bm.length ? "block" : "none";
  $("predStart").innerHTML = predictorHtml();
  $("stEmpty").style.display = $("predStart").innerHTML ? "none" : "block";
  const bs = questionBankStats();
  $("bankStats").innerHTML = '<div class="st-mini-h">📚 Your question log</div>' +
    '<div class="bank-row"><b>' + bs.done + '</b> done · <b>' + bs.fresh + '</b> you haven\'t seen</div>' +
    '<div class="bank-bar"><i style="width:' + Math.round(bs.done / Math.max(1, bs.total) * 100) + '%"></i></div>' +
    '<p class="small muted" style="margin:6px 0 0">' + (bs.fresh ? "Every question you see is recorded" + (signedIn() ? " to your account" : " on this device") + ", and new sets only use questions you haven't done until a section runs out." : "You've done every question. Repeats now start with the ones you did longest ago.") + "</p>";
  const secName = isAct ? ({ all: "All four sections", english: "English", math: "Math", reading: "Reading", science: "Science" })[state.cfg.actSection || "all"] : ({ rw: "Reading & Writing", math: "Math", both: "Both sections" })[state.cfg.section];
  $("stSummary").textContent = (isAct ? "ACT" : "SAT") + " · " + secName + " · " + state.cfg.total + " questions";
  try {
    const counts = countsFor(state.cfg), rates = SEC_PER_Q[state.cfg.testType];
    const secs = Object.keys(counts).reduce((t, k) => t + counts[k] * (rates[k] || 75), 0);
    $("stTime").textContent = "About " + Math.max(1, Math.round(secs / 60)) + " min at real-test pace";
  } catch (e) { $("stTime").textContent = ""; }
  $("btnRetryBookmarks").textContent = "⭐ Retry bookmarked questions (" + bm.length + ")";
  renderVocabSummary();
}

function historyKeysFor(rec) {
  return rec.keys || (rec.testType === "act"
    ? (rec.actSection && rec.actSection !== "all" ? [rec.actSection] : ["english", "math", "reading", "science"])
    : (rec.section === "both" ? ["rw", "math"] : [rec.section]));
}
function historySectionLabel(rec) {
  const keys = historyKeysFor(rec);
  if (rec.testType === "act" && keys.length === 4) return "All Four";
  return keys.map((k) => (defByKey(rec.testType, k) || {}).label || k).join(" + ");
}
function renderHistorySummary() {
  const el = $("historyStart");
  const h = profile.history.filter((r) => r.totalAnswered > 0);
  if (!h.length) { el.style.display = "none"; return; }
  el.style.display = "block";
  const avg = Math.round(h.reduce((s, r) => s + r.accuracy, 0) / h.length);
  const best = Math.max(...h.map((r) => r.totalCorrect));
  el.innerHTML = '<h3>Your Recent Attempts</h3>' +
    `<div class="small muted history-summary-line">${h.length} attempt(s) · avg ${avg}% · best ${best} correct</div><div class="history-strip">` +
    h.slice(0, 5).map((r) => {
      const date = new Date(r.finishedAt).toLocaleDateString();
      const type = (r.testType === "sat" ? "SAT" : "ACT") + (r.practiceKind === "topic" ? " · Topic practice" : "");
      const sec = historySectionLabel(r);
      return `<div class="history-item" data-hid="${r.id}"><div class="hi-head"><strong>${type} · ${sec}</strong><span class="hi-meta">${date}</span></div><div class="hi-stats"><span>${r.totalCorrect}/${r.totalAnswered}</span><span>${r.accuracy}%</span><span>${fmtTime(r.elapsed)}</span><span>🪙${r.tokensEarned}</span></div></div>`;
    }).join("") + "</div>";
  el.querySelectorAll(".history-item").forEach((item) => {
    item.addEventListener("click", () => {
      const rid = item.dataset.hid;
      const rec = profile.history.find((h) => h.id === rid);
      if (!rec) return;
      const details = item.querySelector(".history-details");
      if (details && details.classList.contains("open")) { details.classList.remove("open"); return; }
      item.querySelector(".history-details")?.remove();
      const div = document.createElement("div"); div.className = "history-details open";
      div.innerHTML = renderHistoryDetail(rec);
      item.appendChild(div);
      const review = div.querySelector(".reviewHistoryBtn");
      if (review) review.addEventListener("click", (e) => {
        e.stopPropagation();
        if (div.querySelector(".saved-review")) return;
        const area = document.createElement("div"); area.className = "saved-review";
        area.innerHTML = rec.savedPlan && rec.answers ? renderReviewHtml(rec.testType, historyKeysFor(rec), rec.savedPlan, rec.answers) : '<p class="small">Older results saved correctness but not your chosen answers.</p>' + (rec.qlog || []).filter(([id]) => byId(id)).map(([id, correct]) => '<div class="review"><strong>' + escapeHtml(byId(id).q) + '</strong><p>' + (correct ? "Correct" : "Incorrect") + '</p>' + explanationHtml(byId(id), correct ? byId(id).ans : -1) + '</div>').join('');
        div.appendChild(area);
      });
    });
  });
}

function renderHistoryDetail(rec) {
  let html = `<strong>${rec.testType === "sat" ? "SAT" : "ACT"} · ${historySectionLabel(rec)}</strong> · ${rec.total} questions · ${rec.totalCorrect}/${rec.totalAnswered} (${rec.accuracy}%) · ${fmtTime(rec.elapsed)} · ${rec.tokensEarned} tokens earned · best daily streak ${rec.bestStreak}<br><br>`;
  if (rec.secScores) {
    historyKeysFor(rec).forEach((sec) => {
      const s = rec.secScores[sec]; if (!s) return;
      html += `<span class="domain-mini">${defByKey(rec.testType, sec)?.label || sec}: ${s.score != null ? s.score : s.actScale != null ? s.actScale : "Topic accuracy"} (${s.correct}/${s.answered})</span> `;
    });
  }
  html += `<br><br><button class="secondary reviewHistoryBtn" data-rid="${rec.id}">Review Answers</button>`;
  return html;
}


