// ---- MODULE COUNTDOWN (official pacing: SAT R&W 32 min/27 Q, Math 35 min/22 Q; ACT per-section rates) ----
const SEC_PER_Q = { sat: { rw: 71, math: 95 }, act: { english: 36, math: 60, reading: 52.5, science: 52.5 } };
let elimMode = false, timerHidden = false;
function modClockKey() { return curSection() + "_" + state.modIdx; }
function modClockLeft() {
  state.modClock = state.modClock || {};
  const k = modClockKey();
  if (state.modClock[k] == null) state.modClock[k] = Math.round(currentQids().length * ((SEC_PER_Q[state.cfg.testType] || {})[curSection()] || 75));
  return state.modClock[k];
}
function tickModuleClock() {
  try {
    if (state.view !== "test" || state.done || !currentQids().length) return;
    modClockLeft(); state.modClock[modClockKey()]--;
    if (state.modClock[modClockKey()] === 0) showToast("⏰ Time's up for this module. On test day it would end here, but you can keep practicing.");
    paintModuleClock();
  } catch (e) {}
}
function paintModuleClock() {
  const el = $("modTimer"), wrap = $("modTimerWrap"); if (!el) return;
  let t; try { if (state.view !== "test" || !currentQids().length) throw 0; t = modClockLeft(); } catch (e) { wrap.style.visibility = "hidden"; return; }
  wrap.style.visibility = "visible";
  el.textContent = timerHidden ? "⏱" : (t < 0 ? "+" + fmtTime(-t) : fmtTime(t));
  wrap.classList.toggle("low", !timerHidden && t > 0 && t <= 300);
  wrap.classList.toggle("over", !timerHidden && t <= 0);
  $("btnHideTimer").textContent = timerHidden ? "Show" : "Hide";
}
$("btnHideTimer").addEventListener("click", () => { timerHidden = !timerHidden; paintModuleClock(); });
document.addEventListener("click", (e) => { const p = $("navPop"); if (p && p.classList.contains("show") && !e.target.closest(".bb-navwrap")) p.classList.remove("show"); });

// ---- DRILL: a 10-question set from one content domain, least-seen questions first ----
function startDrill(key, domain) {
  // SAT-only keys must never resolve through an ACT config (and vice versa).
  const tt = key === "rw" ? "sat" : key === "english" || key === "reading" || key === "science" ? "act" : state.cfg.testType;
  const d = defByKey(tt, key);
  const ids = sample(BANK[d.bank].filter((q) => q.domain === domain), 10).map((q) => q.id);
  if (!ids.length) return;
  const currentIsDrill = state.keys && state.keys.some((k) => state.plan[k] && state.plan[k].moduleOnly === "drill");
  if (!state.done && !currentIsDrill && Object.keys(state.answers || {}).length) {
    profile.fullPracticeDraft = JSON.parse(JSON.stringify(state));
    saveProfile();
  }
  if (Object.keys(state.answers).length && !state.done && currentIsDrill) finalizeAttempt(false);
  const cfg = Object.assign({}, state.cfg, { testType: tt }, tt === "act" ? { actSection: key } : { section: key, satModule: "full" }, { total: ids.length });
  clearSaved();
  state = newState(cfg, {});
  state.keys = [key]; state.counts = {}; state.counts[key] = ids.length; state.routes = {};
  state.plan = {}; state.plan[key] = { adaptive: d.adaptive, bank: d.bank, moduleOnly: "drill", drillDomain: domain, mods: [ids] };
  sessionStreak = 0; sessionBestStreak = 0; sessionTokensEarned = 0; sessionUnlocks = []; pendingUnlock = null;
  state.view = "test"; save(); render(); scrollTo(0, 0);
}
function restoreFullPractice() {
  if (!profile.fullPracticeDraft) return;
  state = JSON.parse(JSON.stringify(profile.fullPracticeDraft));
  profile.fullPracticeDraft = null;
  saveProfile(); save(); render(); scrollTo(0, 0);
}
// Retry a saved list of questions (bookmarks). Mixed SAT/ACT questions are grouped into sections.
function startCustomSet(ids, label) {
  ids = ids.filter((id) => byId(id));
  if (!ids.length) return;
  const act = ids.some((id) => /^s/.test(id));
  const keyOf = (id) => /^m/.test(id) ? "math" : /^s/.test(id) ? "science" : act ? (byId(id).kind === "reading" ? "reading" : "english") : "rw";
  const tt = act ? "act" : "sat";
  const order = act ? ["english", "math", "reading", "science"] : ["rw", "math"];
  const groups = {}; shuffle(ids).forEach((id) => { (groups[keyOf(id)] = groups[keyOf(id)] || []).push(id); });
  const keys = order.filter((k) => groups[k]);
  if (Object.keys(state.answers).length && !state.done) finalizeAttempt(false);
  const cfg = Object.assign({}, state.cfg, { testType: tt, total: ids.length, section: act ? state.cfg.section : (keys.length > 1 ? "both" : keys[0]), actSection: act ? (keys.length > 1 ? "all" : keys[0]) : state.cfg.actSection });
  clearSaved();
  state = newState(cfg, {});
  state.keys = keys; state.counts = {}; state.plan = {}; state.routes = {};
  keys.forEach((k) => { const d = defByKey(tt, k); state.counts[k] = groups[k].length; state.plan[k] = { adaptive: d.adaptive, bank: d.bank, moduleOnly: "drill", drillDomain: label, mods: [groups[k]] }; });
  sessionStreak = 0; sessionBestStreak = 0; sessionTokensEarned = 0; sessionUnlocks = []; pendingUnlock = null;
  state.view = "test"; save(); render(); scrollTo(0, 0);
}
function domainStatsKey(key) {
  const out = {};
  sectionQids(key).forEach((id) => {
    const a = state.answers[id]; if (a == null) return;
    const q = byId(id); const s = out[q.domain] = out[q.domain] || { correct: 0, total: 0 };
    s.total++; if (a === q.ans) s.correct++;
  });
  return out;
}
function bandHtml(label, lo, hi, min, max) {
  const L = ((lo - min) / (max - min)) * 100, R = ((hi - min) / (max - min)) * 100;
  return '<div class="band-wrap"><div class="bl">' + label + '</div><div class="band-track"><div class="band-fill" style="left:' + L + "%;width:" + Math.max(0, R - L) + '%"></div>' +
    '<span class="band-lab" style="left:' + L + '%">' + lo + "</span>" + (hi !== lo ? '<span class="band-lab" style="left:' + R + '%">' + hi + "</span>" : "") +
    '</div><div class="band-ends"><span>' + min + "</span><span>" + max + "</span></div></div>";
}
function resultsExtras() {
  let worst = null;
  state.keys.forEach((k) => { const st = domainStatsKey(k); Object.keys(st).forEach((d) => { const acc = st[d].correct / st[d].total; if (!worst || acc < worst.acc) worst = { k, d, acc }; }); });
  const idk = Object.keys(state.answers).filter((id) => state.answers[id] === -1);
  let h = '<div class="res-cta">' +
    (worst ? '<button type="button" id="btnDrill" data-k="' + worst.k + '" data-d="' + escapeHtml(worst.d) + '">🎯 Drill ' + escapeHtml(worst.d) + " (10 questions)</button>" : "") +
    (profile.fullPracticeDraft ? '<button type="button" class="secondary" id="btnReturnFullPractice">Return to full SAT practice</button>' : '') +
    '<button type="button" class="secondary" id="btnSpend">🎮 ' + (profile.tokens ? "Spend " + profile.tokens + " credit" + (profile.tokens > 1 ? "s" : "") : "Arcade") + "</button></div>";
  if (idk.length) h += '<div class="idk-box"><h3>🤷 Questions you weren\'t sure about (' + idk.length + ')</h3><p class="small muted" style="margin:0">These need teaching, not just correcting. Re-read each explanation in Review answers, then try a drill.</p><ol>' +
    idk.map((id) => { const q = byId(id); return "<li>" + escapeHtml(q.q.split("\n").pop().slice(0, 150)) + ' <span class="small muted">· ' + escapeHtml(q.domain) + "</span></li>"; }).join("") + "</ol></div>";
  return h;
}
function wireResultsExtras() {
  const d = $("btnDrill"); if (d) d.addEventListener("click", () => startDrill(d.dataset.k, d.dataset.d));
  const r = $("btnReturnFullPractice"); if (r) r.addEventListener("click", restoreFullPractice);
  const s = $("btnSpend"); if (s) s.addEventListener("click", () => openArcade());
}



// ---- SCORE PREDICTOR ----
// Combines every attempt, however long, into one estimate:
//  1. Each answered question is scored against its difficulty (easy/medium/hard) with a simple
//     item-response model, P(correct) = 1 / (1 + e^-(ability − difficulty)), so 8/10 on hard
//     questions counts for more than 8/10 on easy ones.
//  2. Recent attempts count more (each older attempt weighs 12% less), so improvement shows up.
//  3. A mild prior pulls tiny samples toward the middle, so 3 lucky answers can't predict a 1600.
//  4. The fitted ability is turned into the share of a real test's mix you'd get right, then run
//     through the selected score curve. The range comes from the model's uncertainty.
const DIFF_B = { easy: -1, medium: 0, hard: 1 };
const sig = (x) => 1 / (1 + Math.exp(-x));
function predictorSectionOf(id, testType) {
  const q = byId(id); if (!q) return null;
  if (/^m/.test(id)) return "math";
  if (/^s/.test(id)) return testType === "act" ? "science" : null;
  if (testType === "act") return q.kind === "reading" ? "reading" : "english";
  return "rw";
}
function fitAbility(items) {
  let th = 0, h = -1;
  for (let it = 0; it < 30; it++) {
    let g = -th; h = -1; // N(0,1) prior
    items.forEach((x) => { const p = sig(th - x.b); g += x.w * (x.c - x.n * p); h -= x.w * x.n * p * (1 - p); });
    const step = g / h; th -= Math.max(-1, Math.min(1, step));
    if (Math.abs(step) < 1e-4) break;
  }
  return { th, se: Math.sqrt(-1 / h) };
}
function predictScores() {
  const hist = (profile.history || []).filter((r) => r.totalAnswered > 0 && r.done && r.scoreEligible !== false && r.practiceKind !== "topic").slice().sort((a, b) => (b.finishedAt || 0) - (a.finishedAt || 0));
  const out = { sat: {}, act: {}, attempts: 0, questions: 0 };
  const buckets = {};
  hist.forEach((r, idx) => {
    const w = Math.pow(0.88, idx), tt = r.testType === "act" ? "act" : "sat";
    let used = false;
    if (Array.isArray(r.qlog) && r.qlog.length) {
      r.qlog.forEach(([id, c]) => {
        const sec = predictorSectionOf(id, tt); if (!sec) return;
        (buckets[tt + "." + sec] = buckets[tt + "." + sec] || []).push({ b: DIFF_B[byId(id).diff] || 0, c, n: 1, w });
        out.questions++; used = true;
      });
    } else {
      // older attempts saved only right/answered per section: treat them as medium questions
      Object.keys(r.secScores || {}).forEach((sec) => {
        const s = r.secScores[sec]; if (!s || !s.answered) return;
        (buckets[tt + "." + sec] = buckets[tt + "." + sec] || []).push({ b: 0, c: s.correct, n: s.answered, w });
        out.questions += s.answered; used = true;
      });
    }
    if (used) out.attempts++;
  });
  const shareOfTest = (th) => (sig(th + 1) + sig(th) + sig(th - 1)) / 3; // real tests mix all three levels
  Object.keys(buckets).forEach((key) => {
    const [tt, sec] = key.split("."), items = buckets[key];
    const n = items.reduce((s, x) => s + x.n, 0);
    const { th, se } = fitAbility(items);
    if (tt === "sat") {
      const maxRaw = sec === "rw" ? 66 : 54, sh = curCurve().sat;
      const toScore = (t) => { const row = CURVE[sec][Math.min(Math.round(shareOfTest(t) * maxRaw), CURVE[sec].length - 1)]; return clampSat(Math.round((row[0] + row[1]) / 2 / 10) * 10 + sh); };
      out.sat[sec] = { point: toScore(th), lo: toScore(th - se), hi: toScore(th + se), n };
    } else {
      const toScale = (t) => Math.max(1, Math.min(36, actScale(sec, Math.round(shareOfTest(t) * ACT_MAX_RAW[sec])) + curCurve().act));
      out.act[sec] = { point: toScale(th), lo: toScale(th - se), hi: toScale(th + se), n };
    }
  });
  if (out.sat.rw && out.sat.math) out.sat.total = { point: out.sat.rw.point + out.sat.math.point, lo: out.sat.rw.lo + out.sat.math.lo, hi: out.sat.rw.hi + out.sat.math.hi };
  // Official current ACT scoring: the Composite is the average of English, Math, and Reading.
  // Science is optional and reported separately (ACT, "Understanding Your ACT Scores", 2025+).
  const actCore = ["english", "math", "reading"].filter((k) => out.act[k]);
  if (actCore.length) {
    const avg = (f) => Math.round(actCore.reduce((s, k) => s + out.act[k][f], 0) / actCore.length);
    out.act.composite = { point: avg("point"), lo: avg("lo"), hi: avg("hi"), partial: actCore.length < 3 };
  }
  return out;
}
function unansweredReminderHtml() {
  let skipped = 0, attempts = 0;
  (profile.history || []).filter((r) => r.done && r.totalAnswered > 0 && Number.isFinite(r.total)).slice(0, 5).forEach((r) => {
    const blank = Math.max(0, (r.total || 0) - (r.totalAnswered || 0));
    if (blank) { skipped += blank; attempts++; }
  });
  let active = 0;
  try {
    if (!state.done && Object.keys(state.answers || {}).length && state.plan) {
      const planned = Object.keys(state.plan).reduce((sum, key) => sum + ((state.plan[key].mods || []).reduce((a, m) => a + (m ? m.length : 0), 0)), 0);
      active = Math.max(0, planned - Object.keys(state.answers).length);
    }
  } catch (e) {}
  if (!active && !skipped) return "";
  const parts = [];
  if (active) parts.push(active + " unanswered in your current session");
  if (skipped) parts.push(skipped + " left blank across your last " + attempts + " finished attempt" + (attempts > 1 ? "s" : ""));
  return '<p class="small muted unanswered-note">Estimates use answered questions only, so skipped questions never lower them. Still, you have ' + parts.join(" and ") + '. A blank and a wrong answer both score zero on test day — aim to answer every question.</p>';
}
function scoreImprovementHtml() {
  const stats = {};
  (profile.history || []).filter((r) => r.testType === "sat" && r.done && r.scoreEligible !== false && r.practiceKind !== "topic").slice(0, 8).forEach((r) => {
    (r.qlog || []).forEach(([id, correct]) => {
      const q = byId(id); if (!q) return;
      const st = stats[q.domain] || (stats[q.domain] = { correct: 0, total: 0 });
      st.correct += correct; st.total++;
    });
  });
  const weak = Object.entries(stats).filter(([, st]) => st.correct < st.total).sort((a,b) => a[1].correct/a[1].total - b[1].correct/b[1].total).slice(0, 3);
  return weak.length ? '<div class="workon score-improvement"><strong>Where your SAT score could improve</strong><p class="small muted">Choose a subject for a separate 10-question personalized drill. Subject practice is saved in your history but never replaces your full SAT practice or changes your predicted score.</p><ul>' + weak.map(([domain, st]) => {
    const section = (DOMAINS.math || []).includes(domain) ? 'math' : 'rw';
    const tip = (STUDY_TOOLS[domain] || [,, 'Review this subject with targeted questions.'])[2];
    return '<li><div><strong>' + escapeHtml(domain) + '</strong>: ' + st.correct + '/' + st.total + ' correct in recent SAT practice tests. ' + escapeHtml(tip) + '</div><button type="button" class="subject-practice-link" data-subject-practice="' + escapeHtml(domain) + '" data-subject-section="' + section + '">Practice ' + escapeHtml(domain) + ' →</button></li>';
  }).join('') + '</ul></div>' : '';
}
function predictorHtml() {
  const p = predictScores();
  if (!p.attempts) return "";
  const conf = p.questions >= 120 ? "high" : p.questions >= 40 ? "medium" : "low";
  const tile = (big, range, label) => '<div class="pred-tile"><div class="pred-num">' + big + '</div><div class="pred-range">' + range + '</div><div class="pred-lbl">' + label + "</div></div>";
  let tiles = "";
  const s = p.sat;
  if (s.total) tiles += tile(s.total.point, s.total.lo + "–" + s.total.hi, "SAT total");
  if (s.rw) tiles += tile(s.rw.point, s.rw.lo + "–" + s.rw.hi, "Reading & Writing · " + s.rw.n + " Q");
  if (s.math) tiles += tile(s.math.point, s.math.lo + "–" + s.math.hi, "Math · " + s.math.n + " Q");
  const a = p.act;
  if (a.composite) tiles += tile(a.composite.point, a.composite.lo + "–" + a.composite.hi, "ACT composite" + (a.composite.partial ? " (sections taken so far)" : ""));
  ["english", "math", "reading", "science"].forEach((k) => { if (a[k]) tiles += tile(a[k].point, a[k].lo + "–" + a[k].hi, "ACT " + defByKey("act", k).label + " · " + a[k].n + " Q"); });
  return '<div class="pred-card"><div class="pred-head"><h3>📈 Predicted score</h3><span class="pred-conf ' + conf + '">' + conf + " confidence</span></div>" +
    '<div class="pred-grid">' + tiles + "</div>" +
    '<p class="small muted" style="margin:8px 0 0">Based on ' + p.questions + " questions across " + p.attempts + " attempt" + (p.attempts > 1 ? "s" : "") +
    " completed practice tests. Topic drills and bookmarked retries are excluded. Harder questions and recent tests count more. Uses the " + curCurve().short + ". " + (conf === "low" ? "Answer more questions to narrow the range." : "") + "</p>" +
    unansweredReminderHtml() +
    '<p style="margin:10px 0 0"><button type="button" class="secondary" data-college-open="predicted">🏛️ Compare with colleges →</button></p>' + scoreImprovementHtml() + "</div>";
}

// ---- AI TUTOR: exclusively Groq, through the site’s Worker or a personal Groq key. ----
const AI_SETTINGS_KEY = "satPrepAI_v1";
let lastAiMeta = { provider: "groq", model: "", usage: null, requestId: "" };
function aiSettings() { try { return JSON.parse(localStorage.getItem(AI_SETTINGS_KEY)) || { provider: "free", groqKey: "" }; } catch (e) { return { provider: "free", groqKey: "" }; } }
function saveAiSettings(s) { try { localStorage.setItem(AI_SETTINGS_KEY, JSON.stringify(s)); } catch (e) {} }
async function aiChat(messages, options = {}) {
  const s = aiSettings();
  lastAiMeta = { provider:"groq", model:"", usage:null, requestId:"help_" + Date.now() + "_" + Math.random().toString(36).slice(2,9) };
  const ask = async (url, body, headers) => {
    const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 45000);
    try {
      const r = await fetch(url, { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, headers || {}), body: JSON.stringify(body), signal: ctrl.signal });
      if (r.status === 429) throw { code: "rate_limited" };
      if (r.status === 401 || r.status === 403) throw { code: "bad_key" };
      if (!r.ok) throw { code: "http", status: r.status };
      const j = await r.json();
      const content = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content || "").trim();
      lastAiMeta = { provider: "groq", model: body.model || "", usage: j.usage || null, requestId: typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : "help_" + Date.now() + "_" + Math.random().toString(36).slice(2,9) };
      return content;
    } finally { clearTimeout(t); }
  };
  if (s.provider === "groq" && s.groqKey) {
    try { return await ask("https://api.groq.com/openai/v1/chat/completions", { model: "llama-3.3-70b-versatile", messages, temperature: 0.4, max_tokens: 1000, ...(options.teaching ? { response_format: { type: "json_object" } } : {}) }, { Authorization: "Bearer " + s.groqKey }); } catch (e) { if (typeof API_BASE !== "string") throw e; }
  }
  if (typeof API_BASE !== "string") throw { code: "site_only" };
  const askSite = async () => {
    const ctrl = new AbortController(); const timer = setTimeout(() => ctrl.abort(), 60000);
    try {
      const r = await fetch(API_BASE + "/api/ai", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ messages, teaching: !!options.teaching, noAnswer: !!options.noAnswer, correctLetter: options.correctLetter || "", kind: options.kind || "" }), signal: ctrl.signal });
      const j = await r.json();
      if (!r.ok) throw { code: j.code || "http", status: r.status, retryAfter: j.retryAfter };
      if (!j.content) throw { code: "empty" };
      lastAiMeta = { provider: j.provider || "groq", model: j.model || "", usage: j.usage || null, requestId: j.requestId || (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : "help_" + Date.now() + "_" + Math.random().toString(36).slice(2,9)) };
      return j.content;
    } finally { clearTimeout(timer); }
  };
  try { return await askSite(); }
  catch (e) {
    const transient = e && (e.code === "upstream" || e.code === "http" || e.code === "empty");
    const shortGroqWait = e && e.code === "rate_limited" && (e.retryAfter || 60) <= 5;
    if (transient || shortGroqWait) {
      await new Promise((r) => setTimeout(r, shortGroqWait ? Math.max(1000, (e.retryAfter || 3) * 1000) : 1200));
      return await askSite();
    }
    throw e;
  }
}
function aiErrorText(e) {
  return e && e.code === "no_key" ? "The AI tutor isn't set up on this site yet. The written explanations and study tools are available below." :
    e && e.code === "site_only" ? "Open the published site to use the AI tutor, or add your own Groq key in Account." :
    e && e.code === "server_key_invalid" ? "The AI tutor needs updating. Your written explanations still work." :
    e && e.code === "app_rate_limited" ? "You’ve reached this session’s tutor limit. Retry in about " + Math.ceil((e.retryAfter || 60) / 60) + " minute(s)." :
    e && e.code === "rate_limited" ? "The AI tutor is at its limit. Retry in about " + Math.ceil((e.retryAfter || 60) / 60) + " minute(s)." :
    e && e.code === "invalid_response" ? "The AI tutor's explanation came back incomplete. Try asking again." :
    e && e.code === "upstream" ? "The AI tutor is temporarily unavailable. Please retry." :
    e && e.code === "forbidden" ? "The tutor only works on funsat.bid. Open the app there to use it." :
    e && e.code === "bad_key" ? "Your Groq key was rejected. Check it in 👤 Account → AI tutor." :
    e && e.code === "empty" ? "The AI tutor didn't answer that time. Try asking again." :
    e && e.name === "AbortError" ? "The AI took too long to answer. Try again." :
    "Couldn't reach the AI. Check your internet connection and try again.";
}

// ---- TEST TOOLS: graphing calculator (Desmos), AI calculator walkthroughs, highlighter, line reader ----
// Desmos's own API gives the exact Desmos calculator (same features, keypad and keyboard shortcuts).
// The key below is Desmos's public demo key; request your own free key at desmos.com/api for production.
const DESMOS_SRC = "https://www.desmos.com/api/v1.12/calculator.js?apiKey=21df8e7b72f840be8a2ff4806885b45d";
const MATHJS_SRC = "https://cdnjs.cloudflare.com/ajax/libs/mathjs/12.4.2/math.min.js";
const CALC_AI_RULES = "You can type into the student's graphing calculator (it is Desmos). To show them how, put each calculator entry on its own line as [[calc: <expression>]] using Desmos syntax, e.g. [[calc: y=x^2-5x+6]] or [[calc: y=2x+3]] or [[calc: f(4)/f(2)]]. Use 1-5 entries in the order the student should type them, and say in one short sentence each what to look for (an intersection, an x-intercept, a vertex, a value). Only use [[calc: ...]] when the calculator genuinely helps. No greetings or filler; answer only what was asked, in plain text with simple parentheses.";

function parseCalcSteps(text) {
  const exprs = [];
  const clean = String(text || "").replace(/\[\[\s*calc\s*:\s*([^\]]+?)\s*\]\]/gi, (_, ex) => { exprs.push(ex.trim()); return "“" + ex.trim() + "”"; });
  return { text: clean, exprs };
}
function loadScript(src) {
  return new Promise((res, rej) => {
    const s = document.createElement("script"); s.src = src; s.async = true;
    s.onload = () => res(); s.onerror = () => rej(new Error("blocked"));
    document.head.appendChild(s);
    setTimeout(() => rej(new Error("timeout")), 8000);
  });
}

// Built-in grapher used only when Desmos can't load (offline, or a page that blocks desmos.com).
class FallbackCalc {
  constructor(host) {
    this.host = host; this.colors = ["#c74440", "#2d70b3", "#388c46", "#6042a6", "#fa7e19", "#000000"];
    this.view = { cx: 0, cy: 0, scale: 40 }; this.rows = [];
    host.innerHTML = '<div class="fb-calc"><div class="fb-list" id="fbList"></div><div class="fb-graph"><canvas id="fbCanvas"></canvas><div class="fb-zoom"><button type="button" data-z="in" title="Zoom in">+</button><button type="button" data-z="out" title="Zoom out">−</button><button type="button" data-z="home" title="Default viewport">⌂</button></div></div></div>';
    this.list = host.querySelector("#fbList"); this.canvas = host.querySelector("#fbCanvas");
    host.querySelectorAll("[data-z]").forEach((b) => b.addEventListener("click", () => {
      if (b.dataset.z === "in") this.view.scale *= 1.5; else if (b.dataset.z === "out") this.view.scale /= 1.5; else this.view = { cx: 0, cy: 0, scale: 40 };
      this.draw();
    }));
    let drag = null;
    this.canvas.addEventListener("pointerdown", (e) => { drag = { x: e.clientX, y: e.clientY, cx: this.view.cx, cy: this.view.cy }; this.canvas.setPointerCapture(e.pointerId); });
    this.canvas.addEventListener("pointermove", (e) => { if (!drag) return; this.view.cx = drag.cx - (e.clientX - drag.x) / this.view.scale; this.view.cy = drag.cy + (e.clientY - drag.y) / this.view.scale; this.draw(); });
    this.canvas.addEventListener("pointerup", () => { drag = null; });
    this.canvas.addEventListener("wheel", (e) => { e.preventDefault(); this.view.scale *= e.deltaY < 0 ? 1.1 : 1 / 1.1; this.draw(); }, { passive: false });
    new ResizeObserver(() => this.draw()).observe(this.canvas);
    this.addRow("");
  }
  // Desmos-style input → math.js: y=..., f(x)=..., x=..., (a,b), plain expressions
  parse(raw) {
    let s = raw.replace(/\\left|\\right/g, "").replace(/\\cdot|·|×/g, "*").replace(/÷/g, "/").replace(/−/g, "-").replace(/π|\\pi/g, "pi").replace(/√\s*\(?/g, "sqrt(").replace(/\\sqrt\{([^}]*)\}/g, "sqrt($1)").replace(/\\frac\{([^}]*)\}\{([^}]*)\}/g, "($1)/($2)").replace(/[{}]/g, "").trim();
    if (!s) return null;
    let m;
    if ((m = s.match(/^\(\s*([^,]+),([^)]+)\)$/))) return { kind: "point", x: math.evaluate(m[1], this.scope), y: math.evaluate(m[2], this.scope) };
    if ((m = s.match(/^([a-wz])\s*\(\s*x\s*\)\s*=(.+)$/i))) { const c = math.compile(m[2]); const name = m[1]; this.scope[name] = (x) => c.evaluate(Object.assign({}, this.scope, { x })); return { kind: "fn", f: (x) => c.evaluate(Object.assign({}, this.scope, { x })), label: name + "(x)" }; }
    if ((m = s.match(/^y\s*=(.+)$/))) { const c = math.compile(m[1]); return { kind: "fn", f: (x) => c.evaluate(Object.assign({}, this.scope, { x })) }; }
    if ((m = s.match(/^x\s*=(.+)$/)) && !/x/.test(m[1])) return { kind: "vline", x: math.evaluate(m[1], this.scope) };
    if ((m = s.match(/^([a-wz])\s*=(.+)$/i)) && !/\bx\b/.test(m[2])) { const v = math.evaluate(m[2], this.scope); this.scope[m[1]] = v; return { kind: "value", v }; }
    if (/(^|[^a-z])x([^a-z]|$)/i.test(s)) { const c = math.compile(s); return { kind: "fn", f: (x) => c.evaluate(Object.assign({}, this.scope, { x })) }; }
    return { kind: "value", v: math.evaluate(s, this.scope) };
  }
  addRow(text, after) {
    const row = document.createElement("div"); row.className = "fb-row";
    const color = this.colors[this.list.children.length % this.colors.length];
    row.innerHTML = '<span class="dot"><i style="background:' + color + '"></i></span><input type="text" spellcheck="false" autocomplete="off"><span class="val"></span>';
    row.dataset.color = color;
    const input = row.querySelector("input"); input.value = text || "";
    input.addEventListener("input", () => this.draw());
    input.addEventListener("focus", () => { this.list.querySelectorAll(".fb-row").forEach((r) => r.classList.toggle("active", r === row)); });
    input.addEventListener("keydown", (e) => {
      const rows = [...this.list.children], i = rows.indexOf(row);
      if (e.key === "Enter") { e.preventDefault(); this.addRow("", row).querySelector("input").focus(); }
      else if (e.key === "Backspace" && !input.value && rows.length > 1) { e.preventDefault(); row.remove(); (rows[i - 1] || rows[i + 1]).querySelector("input").focus(); this.draw(); }
      else if (e.key === "ArrowUp" && rows[i - 1]) { e.preventDefault(); rows[i - 1].querySelector("input").focus(); }
      else if (e.key === "ArrowDown" && rows[i + 1]) { e.preventDefault(); rows[i + 1].querySelector("input").focus(); }
    });
    if (after) after.after(row); else this.list.appendChild(row);
    this.draw();
    return row;
  }
  setExpressions(list) {
    this.list.innerHTML = "";
    list.forEach((t) => this.addRow(t));
    this.addRow("");
  }
  clear() { this.list.innerHTML = ""; this.addRow(""); this.view = { cx: 0, cy: 0, scale: 40 }; this.draw(); }
  draw() {
    const c = this.canvas, dpr = window.devicePixelRatio || 1, W = c.clientWidth, H = c.clientHeight;
    if (!W || !H) return;
    c.width = W * dpr; c.height = H * dpr;
    const g = c.getContext("2d"); g.setTransform(dpr, 0, 0, dpr, 0, 0);
    const { cx, cy, scale } = this.view;
    const X = (x) => W / 2 + (x - cx) * scale, Y = (y) => H / 2 - (y - cy) * scale;
    g.fillStyle = "#fff"; g.fillRect(0, 0, W, H);
    const raw = 80 / scale, pow = Math.pow(10, Math.floor(Math.log10(raw))), step = [1, 2, 5, 10].map((k) => k * pow).find((v) => v >= raw);
    const x0 = cx - W / 2 / scale, x1 = cx + W / 2 / scale, y0 = cy - H / 2 / scale, y1 = cy + H / 2 / scale;
    g.lineWidth = 1; g.font = "11px sans-serif"; g.fillStyle = "#555";
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) { g.strokeStyle = "#e6e6e6"; g.beginPath(); g.moveTo(X(x), 0); g.lineTo(X(x), H); g.stroke(); if (Math.abs(x) > step / 2) g.fillText(+x.toPrecision(6), X(x) + 2, Math.min(H - 4, Math.max(12, Y(0) + 12))); }
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) { g.strokeStyle = "#e6e6e6"; g.beginPath(); g.moveTo(0, Y(y)); g.lineTo(W, Y(y)); g.stroke(); if (Math.abs(y) > step / 2) g.fillText(+y.toPrecision(6), Math.min(W - 30, Math.max(2, X(0) + 3)), Y(y) - 2); }
    g.strokeStyle = "#222"; g.lineWidth = 1.5;
    g.beginPath(); g.moveTo(X(0), 0); g.lineTo(X(0), H); g.moveTo(0, Y(0)); g.lineTo(W, Y(0)); g.stroke();
    this.scope = {};
    [...this.list.children].forEach((row) => {
      const val = row.querySelector(".val"), text = row.querySelector("input").value;
      val.textContent = ""; val.classList.remove("err");
      let p; try { p = this.parse(text); } catch (e) { if (text.trim()) { val.textContent = "⚠"; val.classList.add("err"); val.title = e.message; } return; }
      if (!p) return;
      g.strokeStyle = g.fillStyle = row.dataset.color; g.lineWidth = 2.5;
      try {
        if (p.kind === "value") { val.textContent = "= " + (typeof p.v === "number" ? +p.v.toPrecision(10) : String(p.v)); }
        else if (p.kind === "point") { g.beginPath(); g.arc(X(p.x), Y(p.y), 5, 0, Math.PI * 2); g.fill(); }
        else if (p.kind === "vline") { g.beginPath(); g.moveTo(X(p.x), 0); g.lineTo(X(p.x), H); g.stroke(); }
        else {
          g.beginPath(); let pen = false, prev = null;
          for (let px = 0; px <= W; px += 1) {
            const x = cx + (px - W / 2) / scale; let y = p.f(x);
            if (typeof y !== "number" || !isFinite(y) || (prev !== null && Math.abs(y - prev) * scale > H * 2)) { pen = false; prev = null; continue; }
            if (pen) g.lineTo(px, Y(y)); else { g.moveTo(px, Y(y)); pen = true; }
            prev = y;
          }
          g.stroke();
        }
      } catch (e) { val.textContent = "⚠"; val.classList.add("err"); }
    });
  }
}

const calcTool = {
  calc: null, engine: null, loading: null,
  isOpen() { return $("calcPanel").classList.contains("show"); },
  async ensure() {
    if (this.calc) return this.calc;
    if (this.loading) return this.loading;
    this.loading = (async () => {
      const host = $("calcHost");
      try {
        if (!window.Desmos) await loadScript(DESMOS_SRC);
        this.calc = Desmos.GraphingCalculator(host, { keypad: true, expressions: true, settingsMenu: true, zoomButtons: true, expressionsCollapsed: false, border: false });
        this.engine = "desmos"; $("calcEngine").textContent = "Desmos";
      } catch (e) {
        try { if (!window.math) await loadScript(MATHJS_SRC); } catch (e2) {}
        if (!window.math) { host.innerHTML = '<p class="small muted" style="padding:14px">The calculator couldn\'t load. Check your internet connection, or open <a href="https://www.desmos.com/testing/cb-digital-sat/graphing" target="_blank" rel="noopener">the SAT Desmos calculator</a> in a new tab.</p>'; return null; }
        this.calc = new FallbackCalc(host); this.engine = "basic";
        $("calcEngine").innerHTML = 'basic mode · <a href="https://www.desmos.com/testing/cb-digital-sat/graphing" target="_blank" rel="noopener">open Desmos</a>';
      }
      return this.calc;
    })();
    return this.loading;
  },
  async open() {
    $("calcPanel").classList.add("show"); $("btnCalc").classList.add("on"); document.body.classList.add("calc-open");
    await this.ensure();
    if (this.engine === "desmos") this.calc.resize(); else if (this.calc) this.calc.draw();
  },
  close() { $("calcPanel").classList.remove("show"); $("btnCalc").classList.remove("on"); document.body.classList.remove("calc-open"); },
  toggle() { if (this.isOpen()) this.close(); else this.open(); },
  clear() { if (!this.calc) return; if (this.engine === "desmos") this.calc.setBlank(); else this.calc.clear(); },
  // Type the AI's steps into the calculator one at a time so the student can watch the order.
  async demo(exprs) {
    await this.open();
    if (!this.calc) return;
    this.clear();
    for (let i = 0; i < exprs.length; i++) {
      await new Promise((r) => setTimeout(r, i ? 700 : 150));
      if (this.engine === "desmos") this.calc.setExpression({ id: "ai" + i, latex: exprs[i] });
      else this.calc.setExpressions(exprs.slice(0, i + 1));
    }
    if (this.engine === "desmos") { try { this.calc.setMathBounds({ left: -10, right: 10, bottom: -10, top: 10 }); } catch (e) {} }
  },
  async askAI(text) {
    const msg = $("calcAiMsg"); text = String(text || "").trim() || "Show me how to solve this question in the graphing calculator.";
    let q = null; try { if (state.view === "test") q = byId(currentQids()[state.qi]); } catch (e) {}
    msg.textContent = "Thinking…";
    try {
      const ctx = "You are a friendly SAT/ACT tutor helping a high-school student use the graphing calculator. Reply in under 90 words, plain text.\n" + CALC_AI_RULES +
        (q ? "\nCurrent question: " + q.q + "\nChoices: " + q.choices.map((c, i) => String.fromCharCode(65 + i) + ") " + c).join("  ") +
          (state.answers[q.id] == null ? "\nThe student has NOT answered yet: show the calculator method but do not state which choice is correct." : "\nCorrect answer: " + String.fromCharCode(65 + q.ans)) : "");
      const parsed = parseCalcSteps(await aiChat([{ role: "system", content: ctx }, { role: "user", content: text }]));
      renderAiText(msg, parsed.text);
      if (parsed.exprs.length) this.demo(parsed.exprs);
    } catch (e) {
      msg.textContent = aiErrorText(e);
    }
  }
};
$("btnCalc").addEventListener("click", () => calcTool.toggle());
$("calcClose").addEventListener("click", () => calcTool.close());
$("calcClear").addEventListener("click", () => calcTool.clear());
$("calcWide").addEventListener("click", () => { $("calcPanel").classList.toggle("wide"); document.body.classList.toggle("calc-wide", $("calcPanel").classList.contains("wide")); setTimeout(() => { if (calcTool.engine === "desmos") calcTool.calc.resize(); else if (calcTool.calc) calcTool.calc.draw(); }, 50); });
