    const bg = ctx.createLinearGradient(0, 0, 0, H); bg.addColorStop(0, '#1e1b4b'); bg.addColorStop(1, '#0a0f1f');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    drawGameHud(ctx, W, 'BUBBLE SHOOTER', 'SCORE ' + this.score + '  ·  SHOTS ' + this.shots);
