  coupe:  [[-4, .52], [-12, .59], [-22, .50], [-28, .36]],
  wedge:  [[-4, .56], [-11, .62], [-20, .51], [-26, .34]],
  muscle: [[-4, .60], [-12, .65], [-22, .54], [-29, .38]],
  super:  [[-3, .63], [-10, .68], [-19, .53], [-25, .33]],
  ev:     [[-4, .52], [-13, .57], [-26, .54], [-34, .42]]
