  constructor(canvas, arcade) { this.canvas = canvas; this.arcade = arcade; this.ctx = canvas.getContext('2d'); this.name = 'Neon Racing'; this.key = 'racing'; this.W = 760; this.H = 460; this.smooth = true; this.reset(); }
  car() { return DriftCircuit.carFor('racing'); }
  theme() { return Scene3D.THEMES[DriftCircuit.garage().theme] || Scene3D.THEMES.night; }
  mode() { return DriftCircuit.garage().raceMode || 'traffic'; }
  reset() {
    this.stopAudio();
    const g = DriftCircuit.garage();
    this.paint = g.paint; this.wheels = g.wheels;
    this.buildTrack();
    this.playerX = 0; this.playerZ = 0; this.steerAngle = 0; this.lateralVel = 0; this.slip = 0; this.drifting = false; this.speed = NeonRacing.ROAD.maxSpeed * 0.14;
    this.score = 0; this.distance = 0; this.lives = 3; this.overtakes = 0; this.combo = 1;
    this.traffic = []; this.spawnZ = 0; this.started = false; this.over = false; this.banked = false; this.earned = 0;
    this.flash = 0; this.shake = 0; this.hitCooldown = 0; this.wallPush = 0; this.touch = {}; this.smoke = []; this.sparks = []; this.now = 0;
    this.renderPlayerX = 0; this.steerSmoothed = 0;
    this.ai = []; this.laps = 0; this.position = 1; this.lapDistance = 26000; this.finished = false;
    if (this.mode() === 'circuit') { for (let i = 0; i < 3; i++) {
      const x = [-0.5, 0, 0.5][i], z = 1200 + i * 900;
      this.ai.push({ x, z, renderX: x, renderZ: z, speed: NeonRacing.ROAD.maxSpeed * (0.66 + i * 0.05), paint: ['blue', 'green', 'orange'][i], carKey: ['coupe90', 'rally', 'sport'][i], wheelColor: ['silver', 'gold', 'black'][i], wing: ['lip', 'gt', 'duck'][i], decal: i === 1 ? 'stripes' : 'none', lap: 0 });
    } }
    this.audio = null;
    try { if (RacingGL.available()) this.buildTrack3D(this.theme()); } catch (e) {}
  }
  carProfile() { return DriftCircuit.garage(); }
  // Track generation: hills + curves repeat deterministically so scenery stays stable.
