    if (!this.started || this.over) { if (this.audio) { try { this.audio.eg.gain.value = 0; this.audio.ng.gain.value = 0; } catch (e) {} } return; }
    if (!this.audio) this.audio = startCarAudio(DriftCircuit.garage().raceCar);
    const k = this.arcade._heldKeys || {};
