        ctx.beginPath(); ctx.moveTo(a.cl.x, a.cl.y); ctx.lineTo(a.wallL.x, a.wallL.y); ctx.lineTo(b.wallL.x, b.wallL.y); ctx.lineTo(b.cl.x, b.cl.y); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(a.cr.x, a.cr.y); ctx.lineTo(a.wallR.x, a.wallR.y); ctx.lineTo(b.wallR.x, b.wallR.y); ctx.lineTo(b.cr.x, b.cr.y); ctx.closePath(); ctx.fill();
