    if (!this.track3d || this.track3d.themeRef !== theme || this.track3d.pathRef !== this.path) this.buildTrack3D(theme);
    const S = DriftCircuit.GL_SCALE, tier = RacingGL.tierDef(), cam = this.cam;
    const cp = Math.cos(cam.pitch), sp = Math.sin(cam.pitch);
    const eye = [cam.x * S, cam.h * S, cam.y * S];
    const fwd = [Math.cos(cam.yaw) * cp, -sp, Math.sin(cam.yaw) * cp];
    const up = [Math.cos(cam.yaw) * sp, cp, Math.sin(cam.yaw) * sp];
    const fov = 2 * Math.atan(H / (2 * cam.focal));
