    // circuit. Without this the 2.5x world ran straight past the far plane and
    // the track vanished, leaving a flat field of ground colour.
    const K = DriftCircuit.WORLD_SCALE;
    if (!RacingGL.begin(W, H, theme, { near: 360 * S * K, far: 1250 * S * K })) return false;
    RacingGL.setCamera(eye, [eye[0] + fwd[0] * 10, eye[1] + fwd[1] * 10, eye[2] + fwd[2] * 10], up, fov, 12 * S, 1100 * S, .56);
    const I = RacingGL.matrices.mIdent();
    const groundC = RacingGL.hexRgb(theme.ground).map((c) => c * .8);
    RacingGL.drawMesh(RacingGL.mesh('disk'), RacingGL.matrices.mPose(0, -0.6, 0, 0, 130, 1, 130), groundC);
    const basis = RacingGL.cameraBasis();
    if (basis) {
      const billboard = (px, py, pz, scale) => [basis.right[0] * scale, basis.right[1] * scale, basis.right[2] * scale, 0, basis.fwd[0] * scale, basis.fwd[1] * scale, basis.fwd[2] * scale, 0, basis.up[0] * scale, basis.up[1] * scale, basis.up[2] * scale, 0, px, py, pz, 1];
      const sunP = [eye[0] + fwd[0] * 105, eye[1] + 24, eye[2] + fwd[2] * 105];
      RacingGL.drawMesh(RacingGL.mesh('disk'), billboard(sunP[0], sunP[1], sunP[2], 9), [1, .68, .26], { emissive: 1, alpha: .95 });
      for (let m = 0; m < 18; m++) {
        const ma = m / 18 * Math.PI * 2, mr = 92 + (m % 3) * 12, mh = 8 + (m % 4) * 3;
        RacingGL.drawMesh(RacingGL.mesh('cone'), RacingGL.matrices.mPose(Math.sin(ma) * mr, -4, Math.cos(ma) * mr, 0, 7 + (m % 3) * 2, mh, 7 + (m % 3) * 2), RacingGL.hexRgb(theme.prop).map((c) => c * .55));
      }
    }
